                ? new QteBranchTarget { TerminalOutcomeId = DarenTerminalOutcomeId }
                : new QteBranchTarget { NextChapterId = nextBeatId },
            Fail = isTerminal
                ? new QteBranchTarget { TerminalOutcomeId = DarenTerminalOutcomeId }
                : new QteBranchTarget { NextChapterId = nextBeatId }
        };

